`timescale 1ns / 1ps

// Low-pass FIR filter that keeps one output for every DECIM inputs.
//
// The filter removes everything outside the band that survives the lower
// output rate, so that nothing folds back (aliases) onto the wanted signal.
// The same real coefficients are applied to I and to Q.
//
// Coefficients: fir_coeffs.mem, NTAPS signed 16-bit Q15 values that add up
// to 1.0 (generated by python/generate_tables.py).
//
// A result is only computed for the samples that are kept, so the
// multipliers do useful work on one input in every DECIM.

module fir_decimator #(
    parameter NTAPS = 48,
    parameter DECIM = 4
)(
    input wire               clk,
    input wire               rst,

    input wire signed [15:0] in_re,
    input wire signed [15:0] in_im,
    input wire               in_valid,

    output reg signed [15:0] out_re,
    output reg signed [15:0] out_im,
    output reg               out_valid
);

    reg signed [15:0] coeff [0:NTAPS-1];

    initial begin
        $readmemh("fir_coeffs.mem", coeff);
    end

    // The NTAPS-1 previous inputs; index 0 is the most recent.
    reg signed [15:0] hist_re [0:NTAPS-2];
    reg signed [15:0] hist_im [0:NTAPS-2];

    reg [7:0] phase;                        // counts 0 .. DECIM-1

    reg signed [39:0] acc_re;
    reg signed [39:0] acc_im;

    integer k;

    // Round to nearest, drop the 15 fraction bits, clip to 16 bits.
    function signed [15:0] round_sat;
        input signed [39:0] acc;
        reg   signed [39:0] r;
        begin
            r = (acc + 40'sd16384) >>> 15;
            if (r > 40'sd32767)
                round_sat = 16'sd32767;
            else if (r < -40'sd32768)
                round_sat = -16'sd32768;
            else
                round_sat = r[15:0];
        end
    endfunction

    always @(posedge clk) begin

        if (rst) begin

            for (k = 0; k < NTAPS-1; k = k + 1) begin
                hist_re[k] <= 16'sd0;
                hist_im[k] <= 16'sd0;
            end

            phase     <= 8'd0;
            out_re    <= 16'sd0;
            out_im    <= 16'sd0;
            out_valid <= 1'b0;

        end
        else begin

            out_valid <= 1'b0;

            if (in_valid) begin

                // Shift the new sample into the history.
                for (k = NTAPS-2; k > 0; k = k - 1) begin
                    hist_re[k] <= hist_re[k-1];
                    hist_im[k] <= hist_im[k-1];
                end
                hist_re[0] <= in_re;
                hist_im[0] <= in_im;

                if (phase == DECIM-1) begin

                    phase <= 8'd0;

                    // y = coeff[0]*newest + coeff[1]*previous + ...
                    acc_re = in_re * coeff[0];
                    acc_im = in_im * coeff[0];

                    for (k = 1; k < NTAPS; k = k + 1) begin
                        acc_re = acc_re + hist_re[k-1] * coeff[k];
                        acc_im = acc_im + hist_im[k-1] * coeff[k];
                    end

                    out_re    <= round_sat(acc_re);
                    out_im    <= round_sat(acc_im);
                    out_valid <= 1'b1;

                end
                else begin
                    phase <= phase + 8'd1;
                end

            end

        end

    end

endmodule
